/* ---- lookups ---- */
export function entityName(id: string): string {
  const hub = HUBS.find((h) => h.id === id);
  if (hub) return hub.name;
  const store = DARK_STORES.find((s) => s.id === id);
  if (store) return store.name;
  const od = OD_NETWORK.find((o) => o.id === id);
  if (od) return `${od.emirate} On-Demand`;
  return id;
}

export function perfOf(id: string): PerfEntity | null {
  return PERFORMANCE.find((p) => p.id === id) ?? null;
}

export function zoneInfo(emirate: string, zone: string): ZoneInfo | null {
  return ZONES.find((z) => z.emirate === emirate && z.zone === zone) ?? null;
}

export function costRowsFor(id: string): CostRow[] {
  return COST_TO_SERVE.filter((c) => c.id === id);
}

/* ---- geo + formatting helpers ---- */
export function haversineKm(lat1: number, lon1: number, lat2: number, lon2: number): number {
  const R = 6371;
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLon = ((lon2 - lon1) * Math.PI) / 180;
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos((lat1 * Math.PI) / 180) * Math.cos((lat2 * Math.PI) / 180) * Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

export function fmtNum(n: number, digits = 1): string {
  return n.toLocaleString("en-US", { minimumFractionDigits: digits, maximumFractionDigits: digits });
}

export function fmtInt(n: number): string {
  return n.toLocaleString("en-US", { maximumFractionDigits: 0 });
}

export function fmtAed(n: number, digits = 2): string {
  return `${fmtNum(n, digits)} AED`;
}
